#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define BASE 1000000000u

typedef struct {
    uint32_t *d;
    size_t len;
    size_t cap;
} Big;

static int big_reserve(Big *x, size_t need) {
    if (x->cap >= need) return 1;
    size_t new_cap = x->cap ? x->cap : 4;
    while (new_cap < need) new_cap *= 2;
    uint32_t *p = (uint32_t *)realloc(x->d, new_cap * sizeof(uint32_t));
    if (!p) return 0;
    x->d = p;
    x->cap = new_cap;
    return 1;
}

static int big_init(Big *x, uint32_t value) {
    x->d = NULL;
    x->len = 0;
    x->cap = 0;
    if (!big_reserve(x, 1)) return 0;
    x->d[0] = value;
    x->len = 1;
    return 1;
}

static void big_free(Big *x) {
    free(x->d);
    x->d = NULL;
    x->len = 0;
    x->cap = 0;
}

static int big_add(const Big *a, const Big *b, Big *out) {
    size_t max_len = a->len > b->len ? a->len : b->len;
    if (!big_reserve(out, max_len + 1)) return 0;

    uint64_t carry = 0;
    for (size_t i = 0; i < max_len; ++i) {
        uint64_t sum = carry;
        if (i < a->len) sum += a->d[i];
        if (i < b->len) sum += b->d[i];
        out->d[i] = (uint32_t)(sum % BASE);
        carry = sum / BASE;
    }

    out->len = max_len;
    if (carry) out->d[out->len++] = (uint32_t)carry;
    while (out->len > 1 && out->d[out->len - 1] == 0) --out->len;
    return 1;
}

static void big_swap(Big *a, Big *b) {
    Big tmp = *a;
    *a = *b;
    *b = tmp;
}

static void big_print(const Big *x) {
    printf("%u", x->d[x->len - 1]);
    for (size_t i = x->len - 1; i-- > 0;) {
        printf("%09u", x->d[i]);
    }
    putchar(10);
}

int main(int argc, char **argv) {
    if (argc != 2) return 1;

    char *end = NULL;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (argv[1][0] == 0 || argv[1][0] == '-' || (end && *end != 0)) return 1;

    Big a = {0}, b = {0}, c = {0};
    if (!big_init(&a, 0) || !big_init(&b, 1) || !big_init(&c, 0)) {
        big_free(&a);
        big_free(&b);
        big_free(&c);
        return 1;
    }

    for (unsigned long long i = 0; i < n; ++i) {
        if (!big_add(&a, &b, &c)) {
            big_free(&a);
            big_free(&b);
            big_free(&c);
            return 1;
        }
        big_swap(&a, &b);
        big_swap(&b, &c);
    }

    big_print(&a);

    big_free(&a);
    big_free(&b);
    big_free(&c);
    return 0;
}
